/// <summary>
/// Document handler class to handle adhoc registration postings.
/// </summary>
public class TFMPostAdhocRegistration extends TFMDocumentHandler
{
    Str                         registrationType;
    TFMDocumentHandler          docHandler;

}

Method.Source:
    public TFMDocumentHandler subHandler()
    {
        TFMDocumentTypeAttribute    docTypeAttribute;
        DictMethod                  Method;
        if (docHandler)        
        {
            return docHandler;
        }
		docTypeAttribute = new TFMDocumentTypeAttribute(subStr(classStr(TFMPostAdhocRegistration),4,100), request.ContentType());
        docHandler = TFMGetRegistrationConfiguration::getClassFromSysAttribute(classStr(TFMDocumentHandler), docTypeAttribute);
        new ExecutePermission().assert();
        if (docHandler == null)
        {
            resultStr = strFmt("@TFM:CouldNotFindAppropriateClass",subStr(classStr(TFMPostAdhocRegistration),4,100), request.ContentType());
            return null;
        }
        Method = TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classIdGet(docHandler),docTypeAttribute);
        if (Method == null)
        {
            resultStr = strFmt("@TFM:CouldNotFindAppropriateMethod",subStr(classStr(TFMPostAdhocRegistration),4,100), request.ContentType(),classId2Name(classIdGet(docHandler)));
            return null;            
		}

        docHandler.parmMethod(Method);
        return docHandler;        
    }

/// <summary>
///
/// </summary>
/// <returns></returns>
public XML getResult()
{        
    return docHandler ? docHandler.getResult() : '';
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public str getResultStr()
{

    return docHandler && docHandler.getResultStr() ? docHandler.getResultStr() : resultStr;
}

public Common getResultTable()
{
    Common ret;

    ret = docHandler && docHandler.getResultTable() ? docHandler.getResultTable() : null;

    return ret;
}

public Set getDocumentTypes()
{
    Set retMap = new Set(Types::String);
    retMap.add(subStr(classStr(TFMPostAdhocRegistration),4,100));
    return retMap;
}

public TFMDocumentContentSubject getDocumentContentSubject()
{
    TFMDocumentContentSubject ret;

    ret = registrationType;

    return ret;
}

public void process()
{
    registrationType = request.ContentType();

    this.findClass();

}

    protected void findClass()
    {
        TFMDocumentTypeAttribute    docTypeAttribute;
        DictMethod                  Method;
        XML                         retXML;

        docHandler = this.subHandler();
        if(!docHandler)
        {
            resultStr = "@TFM:Nohandlersetupfortheadhocregistr";
            return;
        }
        Method = docHandler.parmMethod();
        if (!method)
        {
            docTypeAttribute = new TFMDocumentTypeAttribute(subStr(classStr(TFMPostAdhocRegistration),4,100), request.ContentType());
            Method = TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classIdGet(docHandler),docTypeAttribute);
        }
        docHandler.parmMessageId(messageId);
        if( requestXml != null)
        {
            docHandler.setRequestXml(requestXml);
        }
        docHandler.setRequestObject(request);
        docHandler.fillInParms();
        docHandler.preProcess();
        new ExecutePermission().assert();
        new DictClass(classIdGet(docHandler)).callObject(Method.name(),docHandler);
        retXML = docHandler.getResult();
        if (retXML != '')
        {
			if (resultXml  == null)
            {
                resultXml = new XmlDocument();
            }
            resultXml.loadXml(retXML);
        }

        resultStr = docHandler.getResultStr();
        CodeAccessPermission::revertAssert();
    }
